solution.solution.js:
function factorial(n) {
  if (!Number.isInteger(n) || n < 0) throw new RangeError(`not a whole number from 0 up: ${n}`);
  let result = 1n;
  for (let i = 2n; i <= BigInt(n); i++) result *= i;
  return result;
}

function digitSum(big) {
  let sum = 0;
  for (const digit of big.toString()) sum += Number(digit);
  return sum;
}

unitTests:
test("factorials", () => {
  checkEq(factorial(0), 1n);
  checkEq(factorial(5), 120n);
  checkEq(factorial(25), 15511210043330985984000000n);
  checkEq(typeof factorial(3), "bigint");
  checkThrows(() => factorial(-1), RangeError);
  checkThrows(() => factorial(2.5), RangeError);
});

test("digit sums", () => {
  checkEq(digitSum(0n), 0);
  checkEq(digitSum(12345n), 15);
  checkEq(digitSum(factorial(100)), 648);
});

